/**
 * Scoring — golden dataset.
 *
 * Every expected value here is computed BY HAND from the specification, not captured from the
 * implementation. A golden file generated by the code under test only proves the code is
 * stable; it cannot prove it is correct, and it would happily enshrine v1's errors.
 *
 * The shrinkage table in spec §10.2 (n=1 → w=0.17, n=5 → 0.50, n=12 → 0.71, n=30 → 0.86) is
 * asserted directly, so a change to the formula fails here rather than quietly shifting every
 * result in a cycle.
 *
 * Refs: FR-SCR-001..013, E2, E3
 */

import { describe, it, expect } from 'vitest'
import {
  computeBiases,
  applyShrinkage,
  applicantFinalScore,
  flagsForApplicant,
  reviewBand,
  DEFAULT_SHRINKAGE_K,
  type EvaluationInput,
} from '../../src/domain/scoring'

/** Helper: an evaluation with all criteria mid-scale unless stated otherwise. */
function evaluation(
  id: string,
  applicantId: string,
  interviewerId: string,
  rawScore: number,
  criterionFractions: number[] = [0.5, 0.5, 0.5],
): EvaluationInput {
  return { evaluationId: id, applicantId, interviewerId, rawScore, criterionFractions }
}

describe('the shrinkage weight table (spec §10.2)', () => {
  it.each([
    [1, 0.17],
    [5, 0.5],
    [12, 0.71],
    [30, 0.86],
  ])('n=%i gives w≈%f', (n, expected) => {
    // w = n/(n+5)
    const evaluations = Array.from({ length: n }, (_, i) =>
      evaluation(`e${i}`, `a${i}`, 'strict', 50),
    )
    const { biases } = computeBiases(evaluations)
    expect(biases.get('strict')!.weight).toBeCloseTo(expected, 2)
  })
})

describe('shrinkage (E3)', () => {
  /**
   * Hand-computed. Two interviewers, one lenient and one strict, four evaluations each.
   *
   *   lenient raw: 80, 80, 80, 80  → mean 80
   *   strict  raw: 40, 40, 40, 40  → mean 40
   *   cohort mean: 60
   *
   *   lenient bias = +20, strict bias = −20
   *   n = 4 each → w = 4/9 = 0.4444
   *
   *   lenient adjusted = 80 − (0.4444 × 20)  = 80 − 8.888 = 71.11
   *   strict  adjusted = 40 − (0.4444 × −20) = 40 + 8.888 = 48.89
   */
  it('pulls a lenient interviewer down and a strict one up, toward the cohort', () => {
    const evaluations = [
      ...Array.from({ length: 4 }, (_, i) => evaluation(`L${i}`, `a${i}`, 'lenient', 80)),
      ...Array.from({ length: 4 }, (_, i) => evaluation(`S${i}`, `b${i}`, 'strict', 40)),
    ]

    const { cohortMean, adjusted } = applyShrinkage(evaluations)

    expect(cohortMean).toBe(60)
    expect(adjusted.find((a) => a.evaluationId === 'L0')!.adjustedScore).toBeCloseTo(71.11, 1)
    expect(adjusted.find((a) => a.evaluationId === 'S0')!.adjustedScore).toBeCloseTo(48.89, 1)
  })

  it('barely adjusts an interviewer with a single evaluation', () => {
    // n=1 → w=0.167. One data point says almost nothing about a person's strictness, and
    // correcting hard on it would be inventing information.
    const evaluations = [
      evaluation('one', 'a', 'newcomer', 90),
      ...Array.from({ length: 20 }, (_, i) => evaluation(`v${i}`, `b${i}`, 'veteran', 50)),
    ]

    const { adjusted } = applyShrinkage(evaluations)
    const newcomer = adjusted.find((a) => a.interviewerId === 'newcomer')!

    // bias ≈ +38.1, w = 0.167 → adjustment ≈ 6.35, so ~83.6 rather than being dragged to 50.
    expect(newcomer.adjustedScore).toBeGreaterThan(80)
    expect(newcomer.shrinkageWeight).toBeCloseTo(0.167, 2)
  })

  it('has NO cliff — the correction is continuous across n', () => {
    // The E3 regression test. v1 switched modes at n=8, so an interviewer's 8th evaluation
    // retroactively rescaled the previous seven and two identically-scored applicants could
    // rank differently based on how many OTHER people their interviewer saw.
    const weightAt = (n: number) => {
      const evaluations = Array.from({ length: n }, (_, i) =>
        evaluation(`e${i}`, `a${i}`, 'x', 70),
      )
      return computeBiases(evaluations).biases.get('x')!.weight
    }

    // The curve w = n/(n+k) is concave: every step is positive and each is SMALLER than the
    // one before. That is the precise property "no cliff" means — the correction decelerates
    // smoothly and never jumps.
    let previousStep = Infinity
    for (let n = 1; n < 20; n++) {
      const step = weightAt(n + 1) - weightAt(n)
      expect(step).toBeGreaterThan(0)
      expect(step).toBeLessThan(previousStep)
      previousStep = step
    }

    // Specifically at n=8, where v1 switched modes and rescaled an interviewer's previous
    // seven evaluations retroactively. Here it is an ordinary increment — and a SMALLER one
    // than the very first step, which is the meaningful comparison: the curve is flattening
    // exactly where v1 jumped.
    const stepAtEight = weightAt(8) - weightAt(7)
    const stepAtOne = weightAt(2) - weightAt(1)
    expect(stepAtEight).toBeLessThan(stepAtOne / 3)
  })

  it('keeps adjusted on the SAME scale as raw (E3, R-023)', () => {
    // A single interviewer has zero measured bias, so adjusted must equal raw exactly. If the
    // two scales ever diverge, this is where it shows.
    const evaluations = Array.from({ length: 6 }, (_, i) =>
      evaluation(`e${i}`, `a${i}`, 'only', 55 + i),
    )
    const { adjusted } = applyShrinkage(evaluations)

    // bias = own mean − cohort mean = 0, since this interviewer IS the cohort.
    for (const a of adjusted) {
      expect(a.adjustedScore).toBeCloseTo(a.rawScore, 5)
    }
  })

  it('does not clamp, so a corrected score may exceed 100', () => {
    // Deliberate. Clamping would silently compress exactly the applicants the correction
    // exists to separate — the value is a corrected measurement, not a percentage.
    const evaluations = [
      ...Array.from({ length: 10 }, (_, i) => evaluation(`h${i}`, `a${i}`, 'harsh', 100)),
      ...Array.from({ length: 10 }, (_, i) => evaluation(`x${i}`, `b${i}`, 'other', 20)),
    ]
    const { adjusted } = applyShrinkage(evaluations)
    const harsh = adjusted.find((a) => a.interviewerId === 'harsh')!

    expect(harsh.adjustedScore).toBeLessThan(100)
    expect(harsh.rawScore).toBe(100)
  })
})

describe('applicant final score (FR-SCR-006)', () => {
  it('is the arithmetic mean of adjusted scores', () => {
    const evaluations = [
      evaluation('e1', 'applicant', 'i1', 70),
      evaluation('e2', 'applicant', 'i2', 50),
    ]
    const { adjusted } = applyShrinkage(evaluations)

    // Both interviewers have n=1, w=0.167. cohort=60, biases +10 and −10.
    // adjusted: 70 − 1.67 = 68.33, 50 + 1.67 = 51.67 → mean 60.
    expect(applicantFinalScore(adjusted)).toBeCloseTo(60, 1)
  })
})

describe('flags (FR-SCR-007..010)', () => {
  const biases = computeBiases([
    ...Array.from({ length: 10 }, (_, i) => evaluation(`x${i}`, `a${i}`, 'veteran', 60)),
  ]).biases

  it('raises HIGH_DISAGREEMENT when the panel spread exceeds 20', () => {
    const evaluations = [
      evaluation('e1', 'applicant', 'veteran', 80),
      evaluation('e2', 'applicant', 'veteran', 45),
    ]
    const { adjusted } = applyShrinkage(evaluations)

    // Averaging away disagreement hides exactly what a committee exists to weigh.
    expect(flagsForApplicant(evaluations, adjusted, biases)).toContain('HIGH_DISAGREEMENT')
  })

  it('does not raise it for a spread of exactly 20', () => {
    // The requirement says "exceeds 20", so 20 itself is not flagged.
    const evaluations = [
      evaluation('e1', 'applicant', 'solo', 60),
      evaluation('e2', 'applicant', 'solo', 40),
    ]
    const { adjusted } = applyShrinkage(evaluations)
    expect(flagsForApplicant(evaluations, adjusted, biases)).not.toContain('HIGH_DISAGREEMENT')
  })

  it('raises CRITERION_FLOOR for a criterion in the bottom quarter of the scale', () => {
    // Generalises "≤ 2 on a 5-point scale": on 1–5, (2−1)/(5−1) = 0.25.
    const evaluations = [evaluation('e1', 'applicant', 'veteran', 75, [0.9, 0.9, 0.25])]
    const { adjusted } = applyShrinkage(evaluations)

    // Note the raw score is high — this is precisely the case a high average can hide.
    expect(flagsForApplicant(evaluations, adjusted, biases)).toContain('CRITERION_FLOOR')
  })

  it('raises SINGLE_EVALUATOR when only one evaluation exists', () => {
    const evaluations = [evaluation('e1', 'applicant', 'veteran', 70)]
    const { adjusted } = applyShrinkage(evaluations)
    expect(flagsForApplicant(evaluations, adjusted, biases)).toContain('SINGLE_EVALUATOR')
  })

  it('raises LOW_CONFIDENCE only when EVERY evaluator is inexperienced', () => {
    const inexperienced = computeBiases([
      evaluation('a', 'x', 'rookie1', 60),
      evaluation('b', 'y', 'rookie2', 60),
    ]).biases

    const evaluations = [
      evaluation('e1', 'applicant', 'rookie1', 70),
      evaluation('e2', 'applicant', 'rookie2', 65),
    ]
    const { adjusted } = applyShrinkage(evaluations)

    expect(flagsForApplicant(evaluations, adjusted, inexperienced)).toContain('LOW_CONFIDENCE')

    // With a veteran on the panel the bias estimate is usable, so no flag — the requirement
    // is "EVERY evaluator has fewer than 5", not "any".
    const mixedPanel = [
      evaluation('e3', 'applicant', 'veteran', 70),
      evaluation('e4', 'applicant', 'rookie1', 65),
    ]
    const mixedBiases = new Map([
      ...biases,
      ...computeBiases([evaluation('r', 'z', 'rookie1', 60)]).biases,
    ])
    const { adjusted: mixedAdjusted } = applyShrinkage(mixedPanel)

    expect(flagsForApplicant(mixedPanel, mixedAdjusted, mixedBiases)).not.toContain(
      'LOW_CONFIDENCE',
    )
  })
})

describe('review bands (FR-SCR-011..013, E2)', () => {
  const C = 8 // the spec's worked example: an 8-place department

  it('reproduces the specification worked example', () => {
    // "ranks 1–6 clear, 7–16 discussed, 17+ below"
    expect(reviewBand(1, C, [])).toBe('clear')
    expect(reviewBand(6, C, [])).toBe('clear')
    expect(reviewBand(7, C, [])).toBe('discuss')
    expect(reviewBand(16, C, [])).toBe('discuss')
    expect(reviewBand(17, C, [])).toBe('below')
  })

  it('places the boundary at exactly 0.75C', () => {
    // 0.75 × 8 = 6, and the band is `rank <= 0.75C`.
    expect(reviewBand(6, 8, [])).toBe('clear')
    expect(reviewBand(7, 8, [])).toBe('discuss')
  })

  it('forces any flagged applicant into discussion regardless of rank (FR-SCR-012)', () => {
    // A clear admit with high disagreement is precisely the case a committee should look at.
    expect(reviewBand(1, C, ['HIGH_DISAGREEMENT'])).toBe('discuss')
    expect(reviewBand(1, C, ['SINGLE_EVALUATOR'])).toBe('discuss')
  })

  it('auto-excludes on CRITERION_FLOOR irrespective of rank (FR-SCR-013)', () => {
    // Checked before rank: a criterion floor is a substantive concern that ranking first
    // does not answer.
    expect(reviewBand(1, C, ['CRITERION_FLOOR'])).toBe('excluded')
    expect(reviewBand(50, C, ['CRITERION_FLOOR'])).toBe('excluded')
  })

  it('scales to any cohort without recalibration (E2)', () => {
    // The whole point of capacity-relative bands: the same rule works for a 4-place and a
    // 40-place department, and never needs touching between cycles.
    expect(reviewBand(3, 4, [])).toBe('clear')
    expect(reviewBand(30, 40, [])).toBe('clear')
    expect(reviewBand(9, 4, [])).toBe('below')
    expect(reviewBand(90, 40, [])).toBe('below')
  })
})

describe('determinism', () => {
  it('produces identical output for identical input, regardless of ordering', () => {
    // FR-DEC-007 demands byte-identical re-runs. Scoring feeds allocation, so if scoring
    // depends on input order then allocation cannot be deterministic either.
    const evaluations = [
      evaluation('e1', 'a1', 'i1', 71.5),
      evaluation('e2', 'a1', 'i2', 64.25),
      evaluation('e3', 'a2', 'i1', 55),
      evaluation('e4', 'a2', 'i2', 88.75),
    ]

    const first = applyShrinkage(evaluations)
    const shuffled = [evaluations[3]!, evaluations[0]!, evaluations[2]!, evaluations[1]!]
    const second = applyShrinkage(shuffled)

    const byId = (r: ReturnType<typeof applyShrinkage>) =>
      Object.fromEntries(r.adjusted.map((a) => [a.evaluationId, a.adjustedScore]))

    expect(byId(second)).toEqual(byId(first))
    expect(second.cohortMean).toBe(first.cohortMean)
  })

  it('uses the documented shrinkage constant', () => {
    expect(DEFAULT_SHRINKAGE_K).toBe(5)
  })
})
